"""
bunpou_meaning_en.py

Locked source of truth for the English translations of Bunpou grammar
content: BunpouEntry.meaningEn/formationEn/usageNotesEn, and
SentenceExample.translationEn (the shared module-neutral class).
apply_bunpou_meaning_en.py reads this and patches
assets/data/bunpou_data.json, so translations live in exactly one
place.

Key format (four content kinds share one dict, disambiguated by
suffix):
    "{id}|meaning"      -> the pattern's meaning gloss
    "{id}|formation"    -> the formation/conjugation rule text
    "{id}|usageNotes"   -> the usage-notes prose
    "{id}|se{i}"        -> the i-th (0-based) sentenceExample's
                            translation

Code-gap note: BunpouEntry.formationEn/localizedFormation did not
exist before this rollout — `formation` was rendered raw in
BunpouDetailScreen with no localization at all. Fixed as part of this
rollout (bunpou_entry.dart + bunpou_detail_screen.dart). Separately,
meaningEn/usageNotesEn already existed as model fields but were never
actually read in BunpouEntry.fromJson — so even already-authored
translations would never have loaded. Both gaps fixed in the same
pass, verified with flutter analyze before any content was authored.

STATUS: DONE, 5,088/5,088 (100%). Total scope, counted directly from
    assets/data/bunpou_data.json (848 real entries, 0 placeholders):
        meaning:            848/848
        formation:          848/848
        usageNotes:         848/848
        sentence examples: 2,544/2,544
        TOTAL:             5,088/5,088
    This corrects the stale "3,839" figure quoted elsewhere in
    CLAUDE.md, which undercounted by not including formation (a field
    that had no English path at all until this rollout) and possibly
    miscounted sentence examples. Completed in 5 batches by JLPT level
    (N5 84 -> N4 132 -> N3 182 -> N2 197 -> N1 253 patterns), same
    verify-patch-apply-commit cycle as every other rollout in this
    codebase. N1 (253 patterns, the largest level) was split across two
    Edit calls purely to stay under a single tool call's practical size
    limit -- both landed in the same commit, no functional split.
"""

